/// <summary>
/// Go 的 json/v2 解 core.CompilerOptions 这组结构体时用到的原语（生成器的共享产物）。
/// 这些形状在 C# 的 Json 包里有既有限制（数组目标不能走 <c>Decode&lt;T&gt;()</c>、OrderedMap 的值
/// 不能是数组），所以在这里显式解。
/// </summary>
internal static class CoreJsonCodec
{
    /// <summary>Go 的 <c>*Tristate</c> 解码：核心是 Tristate 自己的 UnmarshalJSON（非 true/false → TSUnknown）。</summary>
    internal static Tristate DecodeTristate(JsonDecoder decoder)
    {
        var raw = decoder.ReadValue();
        var value = Tristate.TSUnknown;
        value.UnmarshalJSON(raw);
        return value;
    }

    /// <summary>Go 的 <c>[]string</c>：null → nil，否则逐元素解（元素为 null 时 Go 保持零值 ""）。</summary>
    internal static string[]? DecodeStringArrayOrNull(JsonDecoder decoder)
    {
        if (decoder.PeekKind() == JsonKind.Null)
        {
            decoder.ReadToken();
            return null;
        }

        if (decoder.PeekKind() != JsonKind.BeginArray)
        {
            throw new JsonException("json: cannot unmarshal non-array into []string");
        }

        decoder.ReadToken();
        var values = new List<string>();
        while (decoder.PeekKind() != JsonKind.EndArray)
        {
            values.Add(decoder.Decode<string>() ?? "");
        }

        decoder.ReadToken();
        return values.ToArray();
    }

    /// <summary>Go 的 <c>[]PluginImport</c>（值元素：元素为 null 时解成零值结构体，与 Go 一致）。</summary>
    internal static PluginImport[]? DecodePluginImportArrayOrNull(JsonDecoder decoder)
    {
        if (decoder.PeekKind() == JsonKind.Null)
        {
            decoder.ReadToken();
            return null;
        }

        if (decoder.PeekKind() != JsonKind.BeginArray)
        {
            throw new JsonException("json: cannot unmarshal non-array into []PluginImport");
        }

        decoder.ReadToken();
        var values = new List<PluginImport>();
        while (decoder.PeekKind() != JsonKind.EndArray)
        {
            values.Add(decoder.DecodeNew<PluginImport>());
        }

        decoder.ReadToken();
        return values.ToArray();
    }

    /// <summary>
    /// Go 的 <c>*collections.OrderedMap[string, []string]</c>（CompilerOptions.Paths）：null → nil。
    /// 这里不能直接调 <c>OrderedMap.UnmarshalJSONFrom</c>：它的值走 <c>Decode&lt;V&gt;()</c>，而 V = string[]
    /// 是数组目标 —— C# 的 Json 包对数组目标会抛 NeedsInstance（docs/json.md §2 的既有约束）。
    /// 键序保持 JSON 里的出现顺序（Go 的 OrderedMap 语义）。
    /// </summary>
    internal static OrderedMap<string, string[]>? DecodePathsOrNull(JsonDecoder decoder)
    {
        if (decoder.PeekKind() == JsonKind.Null)
        {
            decoder.ReadToken();
            return null;
        }

        if (decoder.PeekKind() != JsonKind.BeginObject)
        {
            throw new JsonException("cannot unmarshal non-object JSON value into Map");
        }

        decoder.ReadToken();
        var map = new OrderedMap<string, string[]>();
        while (decoder.PeekKind() != JsonKind.EndObject)
        {
            var key = decoder.Decode<string>() ?? "";
            map.Set(key, DecodeStringArrayOrNull(decoder)!);
        }

        decoder.ReadToken();
        return map;
    }
}
